<div class="page-heading"><div><span class="eyebrow">Community insights</span><h1>Reports</h1><p class="muted">Reports include active records within your account’s permitted scope.</p></div><?= button('Print reports',['type'=>'button','variant'=>'secondary','data-print'=>true]) ?></div>
<div class="grid grid--2">
<?php foreach (['resident-surveys','barangay-surveys'] as $name): if (!in_array($user['type'],resource($name)['read'],true)) continue; [$reportRows,$total] = resource_rows($name,'',false,1,true); $sum = array_sum(array_map(fn($item)=>is_numeric($item['no_household']) ? (int)$item['no_household'] : 0,$reportRows)); ?>
<section class="card report-card"><span class="eyebrow"><?= e(resource($name)['title']) ?></span><h2><?= number_format($total) ?> submissions</h2><p><?= number_format($sum) ?> reported households across submissions</p><p class="muted">Submissions may describe overlapping households or different periods. This sum is not a deduplicated municipal population estimate.</p><div class="actions"><?= button('View submissions',['href'=>url('records',['resource'=>$name]),'variant'=>'secondary']) ?><?= button('Export full CSV',['href'=>url('export',['resource'=>$name]),'variant'=>'quiet']) ?></div></section>
<?php endforeach; ?>
</div>
<?php [$residentRows,$residentCount] = resource_rows('resident-surveys','',false,1,true); $genderTotals = []; foreach ($residentRows as $survey) { $gender = $survey['gender'] ?: 'Not specified'; $genderTotals[$gender] = ($genderTotals[$gender] ?? 0)+1; } ?>
<section class="card report-card"><h2>Resident survey distribution</h2><?php if (!$residentRows): ?><?= empty_state('No resident survey data yet','Complete a resident survey to populate this report.') ?><?php else: ?><div class="table-scroll"><table><caption>Gender recorded in resident survey submissions</caption><thead><tr><th scope="col">Gender</th><th scope="col">Submissions</th><th scope="col">Share</th></tr></thead><tbody><?php foreach ($genderTotals as $gender=>$total): ?><tr><td><?= e($gender) ?></td><td><?= $total ?></td><td><meter min="0" max="<?= $residentCount ?>" value="<?= $total ?>" aria-label="<?= e($gender) ?> submission share"></meter> <?= round($total/$residentCount*100,1) ?>%</td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
